def roman_to_int(s):
    if not isinstance(s, str) or not s:
        raise ValueError('Input must be a non-empty string')
    if not s.isupper() or not re.match(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$', s):
        raise ValueError('Input must be a valid uppercase Roman numeral')

    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in roman_values:
            total += roman_values[s[i:i+2]]
            i += 2
        else:
            total += roman_values[s[i]]
            i += 1
    return total

