def parse_kv(text):
    if not text:
        return {}

    result = {}
    seen_keys = set()

    for match in text.split(';'):
        match = match.strip()
        if not match:
            continue

        if '=' not in match:
            raise ValueError(f'Invalid pair: {match}')

        key, value = match.split('=', 1)
        key = key.strip()
        value = value.strip()

        if key in seen_keys:
            raise ValueError(f'Duplicate key: {key}')
        if not re.match(r'^[a-z_]+$', key):
            raise ValueError(f'Invalid key: {key}')

        result[key] = value
        seen_keys.add(key)

    return result

