class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, qty, unit_price):
        if qty <= 0 or unit_price < 0:
            raise ValueError("Invalid quantity or unit price")
        if name in self.items:
            self.items[name]['qty'] += qty
            self.items[name]['unit_price'] = unit_price
        else:
            self.items[name] = {'qty': qty, 'unit_price': unit_price}

    def remove(self, name, qty):
        if name not in self.items:
            raise KeyError("Item not found")
        if qty <= 0 or qty > self.items[name]['qty']:
            raise ValueError("Invalid quantity to remove")
        self.items[name]['qty'] -= qty
        if self.items[name]['qty'] == 0:
            del self.items[name]

    def quantity(self, name):
        return self.items.get(name, 0)['qty'] if name in self.items else 0

    def total_value(self):
        return sum(item['qty'] * item['unit_price'] for item in self.items.values())

class TokenBucket:
    def __init__(self, capacity, refill_per_second, clock):
        if capacity < 1 or refill_per_second < 0:
            raise ValueError('Invalid capacity or refill rate')
        self.capacity = capacity
        self.refill_per_second = refill_per_second
        self.clock = clock
        self.tokens = capacity
        self.last_refill_time = self.clock()

    def allow(self):
        current_time = self.clock()
        elapsed_time = current_time - self.last_refill_time
        self.tokens += elapsed_time * self.refill_per_second
        self.tokens = min(self.tokens, self.capacity)
        self.last_refill_time = current_time

        if self.tokens >= 1:
            self.tokens -= 1
            return True
        else:
            return False

    def __repr__(self):
        return f'TokenBucket(capacity={self.capacity}, refill_per_second={self.refill_per_second}, tokens={self.tokens})'

